class BankAccount:
    def __init__(self):
        self.balance = 0

    def deposit(self, amount):
        self.balance += amount

    def withdraw(self, amount):
        if amount > self.balance:
            print("잔액이 부족합니다")
        else:
            self.balance -= amount


account = BankAccount()
n = int(input())
for _ in range(n):
    cmd, amount = input().split()
    amount = int(amount)
    if cmd == "deposit":
        account.deposit(amount)
    elif cmd == "withdraw":
        account.withdraw(amount)
print(f"잔액: {account.balance}원")
